refentry.refsect1:
  &reftitle.parameters;


    exception


generator भित्र throw गरिने Exception।

  &reftitle.examples;



    एउटा generator भित्र exception throw गर्ने


<?php
function gen() {
    echo "Foo\n";
    try {
        yield;
    } catch (Exception $e) {
        echo "Exception: {$e->getMessage()}\n";
    }
    echo "Bar\n";
}

$gen = gen();
$gen->rewind();
$gen->throw(new Exception('Test'));
?>


    &example.outputs;


Foo
Exception: Test
Bar
